    while i<len(c):
        h=struct.unpack_from('<H',c,i)[0]; size=(h&0xfff)+3; end=i+size; i+=2
        if not h&0x8000: out+=c[i:i+4096]; i+=4096; continue
        st=len(out)
        while i<end:
            fb=c[i]; i+=1
            for b in range(8):
                if i>=end: break
                if not fb>>b&1: out.append(c[i]); i+=1
                else:
                    tok=struct.unpack_from('<H',c,i)[0]; i+=2
                    dc=len(out)-st; bc=max((dc-1).bit_length(),4)
                    lm=0xffff>>bc; L=(tok&lm)+3; off=(tok>>(16-bc))+1
                    for _ in range(L): out.append(out[-off])
    return bytes(out)
